effect.shader:
void main(){
    vec2 px = 1.0/acScreenSize;
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c = src.a>0.0? src.rgb/src.a : src.rgb;
    vec3 a = texture2DCv(inputImg.texture, acScreenNorm-px).rgb;
    vec3 b = texture2DCv(inputImg.texture, acScreenNorm+px).rgb;
    vec3 e = (a-b)*strength + 0.5;
    float g = dot(e, vec3(0.333));
    gl_FragColor = vec4(mix(c, vec3(g), amount),1.0)*src.a;
}
